/* Catálogo de materiais. A leitura de uma fonte não atribui veredito ao investigado. */
(() => {
  'use strict';
  const $=id=>document.getElementById(id); let report=window.ARQUIVO_RESEARCH||{items:[],sources:[],queries:[],nextBatch:[]};
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const url=s=>{try{const u=new URL(String(s));return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return '';}};
  const arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>';
  const states={encontrado:'Localizado',acessado:'Acessado',analisado:'Texto examinado',revisado:'Revisão identificada',publicado:'Edição anterior'};
  const formats={documento:'Documento',video:'Vídeo',audio:'Áudio',checagem:'Checagem do veículo',reportagem:'Reportagem',registro:'Registro público'};
  const date=s=>{if(!s)return 'Data não informada';if(/^\d{4}$/.test(s))return s;if(/^\d{4}-\d{2}$/.test(s))return new Intl.DateTimeFormat('pt-BR',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'-01T12:00:00Z'));const d=new Date(/^\d{4}-\d{2}-\d{2}$/.test(s)?s+'T12:00:00Z':s);return Number.isNaN(d.getTime())?String(s):new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'short',year:'numeric',timeZone:'America/Campo_Grande'}).format(d);};
  const text=s=>Array.isArray(s)?s.join('; '):s&&typeof s==='object'?Object.values(s).filter(v=>typeof v==='string').join(' / '):String(s??'');
  const link=(u,label)=>url(u)?`<a href="${esc(url(u))}" target="_blank" rel="noopener noreferrer">${esc(label)} ${arrow}</a>`:`<span>${esc(label)}</span>`;
  let fresh=(report.items||[]).filter(i=>i.id&&i.title&&url(i.url));
  const legacy=(window.ACERVO?.records||[]).filter(r=>r.person==='flavio').map(r=>({id:r.id,title:r.title,url:r.sources[0]?.url,publisher:r.sources[0]?.publisher||'',date:r.statementDate||r.sortDate,year:r.year,format:'checagem',topic:r.topic,stage:'publicado',summary:r.summary,limitations:r.editorialNote||'Ficha herdada da edição anterior. A revisão desta edição não equivale a uma nova revisão humana.',classification:r.verdict,legacy:true,sources:r.sources}));
  let items=[...fresh], itemMap=new Map(items.map(i=>[i.id,i]));
  let sourceMap=new Map((report.sources||[]).map(s=>[s.id,s]));
  let index=new Map(items.map(i=>[i.id,norm([i.title,i.summary,i.publisher,i.topic,...(i.topics||[]),...(i.themes||[]),i.factualQuestion,i.locator,i.transcript?.text||i.transcript?.excerpt||''].map(text).join(' '))]));
  let limit=12,sourceLimit=12;
  const fields=['researchQuery','researchYear','researchTopic','researchFormat','researchPublisher','researchStage','researchClassification','researchFrom','researchTo'];
  function options(id,values,label){$(id).innerHTML=`<option value="all">${label}</option>`+[...new Set(values.filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'pt-BR')).map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');}
  function setup(){
    options('researchYear',items.map(i=>i.year||String(i.date||'').slice(0,4)).filter(y=>/^\d{4}$/.test(String(y))),'Todos os anos');
    options('researchTopic',items.map(i=>i.topic),'Todos os temas');
    options('researchPublisher',items.map(i=>i.publisher),'Todas as fontes');
  }
  function selected(){const q=norm($('researchQuery').value).split(/\s+/).filter(Boolean),year=$('researchYear').value,topic=$('researchTopic').value,format=$('researchFormat').value,publisher=$('researchPublisher').value,stage=$('researchStage').value,classification=$('researchClassification').value,from=$('researchFrom').value,to=$('researchTo').value;
    return items.filter(i=>q.every(t=>index.get(i.id).includes(t))&&(year==='all'||String(i.year||String(i.date||'').slice(0,4))===year)&&(topic==='all'||i.topic===topic)&&(format==='all'||i.format===format)&&(publisher==='all'||i.publisher===publisher)&&(stage==='all'||i.stage===stage)&&(classification==='all'||(classification==='pending'?!i.classification:i.classification===classification))&&(!from||i.date&&i.date.length>=10&&i.date.slice(0,10)>=from)&&(!to||i.date&&i.date.length>=10&&i.date.slice(0,10)<=to)).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||a.title.localeCompare(b.title,'pt-BR'));
  }
  function renderCatalog(){const list=selected();$('researchResults').textContent=`${list.length} materiais encontrados`;const rows=list.slice(0,limit);
    $('researchList').innerHTML=rows.map(i=>`<article class="catalog-row" id="catalogo-${esc(i.id)}"><div class="catalog-meta"><strong>${esc(date(i.date))}</strong><span>${esc(formats[i.format]||'Registro')}</span></div><div class="catalog-body"><h3><button data-research-id="${esc(i.id)}">${esc(i.title)}</button></h3><p>${esc(i.summary||'Metadados disponíveis na ficha.')}</p><div class="catalog-tags"><span>${esc(i.publisher)}</span><span>${esc(i.topic||'Contexto')}</span>${i.legacy?`<span>${esc(i.classification)} / edição anterior</span>`:''}</div></div><div class="catalog-state"><strong>${esc(states[i.stage]||'Aguardando análise')}</strong><small>${i.legacy?'Veredito e referências na ficha original.':'Conclusão própria pendente de revisão editorial.'}</small></div></article>`).join('')||'<p class="catalog-empty">Nenhum material com estes filtros.</p>';
    $('researchMore').hidden=rows.length>=list.length;$('researchShown').textContent=`Exibindo ${rows.length} de ${list.length}`;
  }
  function field(label,value){return `<div class="research-field"><dt>${esc(label)}</dt><dd>${esc(text(value)||'Não informado')}</dd></div>`;}
  function openItem(id,fromHash=false){const i=itemMap.get(id);if(!i)return;if(i.legacy){if($('researchDialog').open)$('researchDialog').close();location.hash='ficha='+encodeURIComponent(id);return;}
    const source=sourceMap.get(i.sourceId),tr=i.transcript||{};
    const sources=(i.sources||[]).map(s=>link(s.url,s.title||s.publisher||'Fonte'));
    $('researchContent').innerHTML=`<div class="dialog-body"><span class="small-label">${esc(formats[i.format]||'REGISTRO')} / ${esc(i.id)}</span><h2 id="researchTitle">${esc(i.title)}</h2><div class="research-dialog-meta"><span>${esc(i.publisher)}</span><span>${esc(date(i.date))}</span><span>${esc(states[i.stage]||'Material localizado')}</span></div><p class="evidence">${esc(i.summary||'')}</p><div class="research-disclaimer">Este índice apresenta o material e seus limites. A classificação própria permanece pendente. Uma conclusão citada de outro veículo pertence ao veículo identificado.</div><section class="detail-section"><h3>Pergunta de apuração</h3><p>${esc(i.factualQuestion||i.factual_question||'Quais fatos este registro permite estabelecer, na data e nas condições descritas?')}</p></section>${i.publicResponse||i.public_response?`<section class="detail-section"><h3>Resposta pública localizada</h3><p>${esc(text(i.publicResponse||i.public_response))}</p></section>`:''}<dl>${field('Localizador',i.locator)}${field('Data da publicação',i.publishedAt||i.published_date||i.publicationDate||i.date)}${field('Data do evento',i.eventDate||i.event_date)}${field('Precisão da data',i.datePrecision||i.date_precision)}${field('Coleta (UTC)',i.collectedAt||report.metadata?.generatedAt)}${field('Revisão identificada',i.review?.reviewer?i.review.reviewer+' / '+date(i.review.reviewedAt):'Pendente. Nenhuma revisão humana identificada neste lote.')}${field('Transcrição',tr.method||'Não produzida pelo projeto')}${field('Conferência do áudio',tr.state||'Não realizada neste lote')}${field('Última alteração (UTC)',i.lastModifiedAt)}${i.actor?field('Autor ou pessoa atribuída',i.actor):''}${i.literalQuote?field('Citação curta publicada',i.literalQuote):''}${i.documentNumber?field('Documento',i.documentNumber):''}${i.relationship?field('Relação com o episódio',i.relationship):''}${i.originGroup?field('Grupo de origem',i.originGroup):''}</dl>${tr.text||tr.excerpt?`<section class="detail-section"><h3>Trecho disponível</h3><p>${esc(tr.text||tr.excerpt)}</p><p class="muted-detail">Método: ${esc(tr.method||'Não informado')}. Consulte a íntegra na origem.</p></section>`:''}<section class="detail-section"><h3>Limitações</h3><p>${esc(text(i.limitations)||'A presença no catálogo não equivale a uma checagem concluída.')}</p></section>${source?`<section class="detail-section"><h3>Procedência</h3><p>${esc(source.name)}. ${esc(source.accessNote||'')}</p></section>`:''}<div class="research-inline-links">${link(i.url,'Abrir fonte original')}${i.mediaUrl?link(i.mediaUrl,'Abrir mídia'):''}${(i.legacyRecordIds||[]).map(id=>`<a href="#ficha=${encodeURIComponent(id)}" data-related-case="${esc(id)}">Ficha anterior relacionada</a>`).join('')}${sources.join(' ')}</div><div class="detail-actions"><button data-copy-research="${esc(i.id)}">Copiar link da ficha</button></div></div>`;
    if(!fromHash)history.pushState(null,'','#registro='+encodeURIComponent(id));$('researchDialog').showModal();document.body.classList.add('modal-open');$('researchDialog').scrollTop=0;
  }
  function renderCoverage(){
    const known=fresh.filter(i=>i.date||i.year),years=Array.from({length:24},(_,i)=>2003+i).reverse();
    $('coverageRows').innerHTML=years.map(y=>{const l=known.filter(i=>Number(i.year||String(i.date).slice(0,4))===y),read=l.filter(i=>['analisado','revisado','publicado'].includes(i.stage)).length,reviewed=l.filter(i=>i.review?.reviewer&&i.review?.reviewedAt).length,previous=legacy.filter(i=>i.year===y).length;return `<tr><td>${y}</td><td class="${!l.length?'coverage-zero':''}">${l.length}</td><td>${read}</td><td>${reviewed}</td><td>${previous}</td><td>${esc([...new Set(l.map(i=>i.topic))].filter(Boolean).join(', ')||'Lacuna neste lote')}</td></tr>`;}).join('');
    const undated=fresh.filter(i=>!i.date&&!i.year).length;$('coverageUndated').textContent=`${undated} materiais sem ano confirmado. A matriz conta materiais deste lote, por ano do evento ou da publicação disponível. As fichas da edição anterior aparecem em coluna separada.`;
    const pending=report.nextBatch||[];$('nextBatchList').innerHTML=pending.map((b,i)=>`<div class="batch-item"><strong>${esc(typeof b==='string'?`Próximo recorte ${i+1}`:b.title||b.scope||b.batch||`Recorte ${i+1}`)}</strong>${esc(text(typeof b==='string'?b:b.note||b.description||b.gap||b.reason||b.action||b))}</div>`).join('')||'<p>Os recortes anteriores a 2019 e a audição integral das entrevistas exigem ampliação.</p>';
    $('queryLog').innerHTML=(report.queries||[]).map(q=>`<li>${esc(typeof q==='string'?q:q.query||q.q||q.expression||q.search||text(q))}<span>${esc(text(q.resultsState||q.result||q.note||q.outcome||q.interval||q.period||q.status))}</span></li>`).join('');
    $('newMaterialCount').textContent=fresh.length;const countNote=$('catalogNewNote');if(countNote)countNote.textContent=String(report.metrics?.newItems??fresh.length)+' novos / '+String(report.metrics?.alreadyInArchive??0)+' já relacionados ao acervo';$('readMaterialCount').textContent=fresh.filter(i=>['analisado','revisado','publicado'].includes(i.stage)).length;$('reviewedAudioCount').textContent=Math.floor(Number(report.metrics?.reviewedAudioSeconds||0)/60)+' min';$('pendingMaterialCount').textContent=fresh.filter(i=>!i.review?.reviewer).length;
  }
  function renderSources(){const q=norm($('sourceSearch').value),nature=$('sourceNature').value;const sources=(report.sources||[]).filter(s=>norm(s.name+' '+s.nature).includes(q)&&(nature==='all'||(nature==='primary'?/oficial|primary|prim.ria|institucional|órgão público/i.test(s.nature):!/oficial|primary|prim.ria|institucional|órgão público/i.test(s.nature))));
    $('sourceCount').textContent=`${sources.length} fontes no mapa`;
    $('sourceMap').innerHTML=sources.slice(0,sourceLimit).map(s=>`<article class="source-card"><span class="source-nature">${esc(s.nature||'Fonte pública')}</span><h3>${link(s.url,s.name)}</h3><dl><div><dt>Responsável</dt><dd>${esc(s.responsible||s.name)}</dd></div><div><dt>Estado</dt><dd>${esc(s.status||'A verificar')}</dd></div><div><dt>Acesso</dt><dd>${esc(s.method||'Consulta editorial')}</dd></div><div><dt>Materiais neste lote</dt><dd>${esc(s.sourceCount??fresh.filter(i=>i.sourceId===s.id).length)}</dd></div><div><dt>Período no lote</dt><dd>${esc((s.periods||[]).join(', ')||'Não delimitado')}</dd></div><div><dt>Rotina automática</dt><dd>${s.intervalMinutes?esc(s.intervalMinutes+' min / planejada'):'Consulta editorial'}</dd></div><div><dt>Última coleta</dt><dd>${s.lastSuccessfulCollectionAt?esc(date(s.lastSuccessfulCollectionAt)):'Consulte o painel de feeds'}</dd></div></dl><p>${esc(text(s.accessNote)||'As permissões e a disponibilidade dependem do publicador.')}</p></article>`).join('');$('sourcesMore').hidden=sourceLimit>=sources.length;
  }
  function renderCorrections(){const history=report.history||[];const notes=(window.ACERVO?.records||[]).filter(r=>r.correction).map(r=>({date:r.correction.date,title:'Retificação do autor: '+r.title,description:r.correction.text,url:r.correction.sourceUrl,recordId:r.id}));
    $('correctionList').innerHTML=[...history,...notes].map(n=>`<article class="correction-entry"><time>${esc(date(n.date||n.at||n.changedAt))}</time><div><h3>${esc(n.title||'Alteração documentada')}</h3><p>${esc(n.description||n.reason||n.summary||n.text||'')}</p>${n.url?link(n.url,'Consultar o registro'):''}${n.recordId?`<a href="#ficha=${encodeURIComponent(n.recordId)}">Abrir ficha relacionada</a>`:''}</div></article>`).join('');
  }
  function sync(){if(location.hash.startsWith('#registro=')){try{openItem(decodeURIComponent(location.hash.slice(10)),true);}catch{return;}}}
  document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.researchId)openItem(b.dataset.researchId);if(b.dataset.copyResearch){try{await navigator.clipboard.writeText(location.href.split('#')[0]+'#registro='+encodeURIComponent(b.dataset.copyResearch));b.textContent='Link copiado';}catch{b.textContent='Use o endereço da barra do navegador';}}});
  fields.forEach(id=>$(id).addEventListener(id==='researchQuery'?'input':'change',()=>{limit=12;renderCatalog();}));
  $('researchClear').addEventListener('click',()=>{fields.forEach(id=>$(id).value=$(id).tagName==='SELECT'?'all':'');limit=12;renderCatalog();});
  $('researchMore').addEventListener('click',()=>{limit+=12;renderCatalog();});
  $('sourceSearch').addEventListener('input',()=>{sourceLimit=12;renderSources();});$('sourceNature').addEventListener('change',()=>{sourceLimit=12;renderSources();});$('sourcesMore').addEventListener('click',()=>{sourceLimit+=12;renderSources();});
  $('researchDialog').addEventListener('close',()=>{if(location.hash.startsWith('#registro='))history.replaceState(null,'','#pesquisa');document.body.classList.toggle('modal-open',!!document.querySelector('dialog[open]'));});
  window.addEventListener('hashchange',sync);window.addEventListener('popstate',()=>{if(!location.hash.startsWith('#registro=')&&$('researchDialog').open)$('researchDialog').close();else sync();});
  function installReport(candidate){
    if(!candidate||candidate.schemaVersion!==1||!Array.isArray(candidate.items)||candidate.items.length>10000)return;
    if(new Date(candidate.metadata?.generatedAt||0)<=new Date(report.metadata?.generatedAt||0))return;
    const prior=Object.fromEntries(fields.map(id=>[id,$(id).value]));
    report=candidate;fresh=(report.items||[]).filter(i=>/^[a-z0-9-]+$/.test(i.id||'')&&i.title&&url(i.url));items=[...fresh];itemMap=new Map(items.map(i=>[i.id,i]));sourceMap=new Map((report.sources||[]).map(s=>[s.id,s]));index=new Map(items.map(i=>[i.id,norm([i.title,i.summary,i.publisher,i.topic,...(i.topics||[]),i.factualQuestion,i.locator,i.transcript?.text||i.transcript?.excerpt||''].map(text).join(' '))]));setup();fields.forEach(id=>{if($(id).tagName!=='SELECT'||[...$(id).options].some(o=>o.value===prior[id]))$(id).value=prior[id];});renderCatalog();renderCoverage();renderSources();renderCorrections();
  }
  document.addEventListener('arquivo-research',e=>installReport(e.detail));
  setup();renderCatalog();renderCoverage();renderSources();renderCorrections();sync();
})();
